do $$ begin
 if exists(select 1 from public.catalogue_variants t join desired_catalogue_variants e on t.id=e.id where t.id is distinct from e.id or t.set_id is distinct from e.set_id or t.card_id is distinct from e.card_id or t.variant_order is distinct from e.variant_order or t.subset is distinct from e.subset or t.card_number is distinct from e.card_number or t.display_name is distinct from e.display_name or t.parallel is distinct from e.parallel or t.serial_cap is distinct from e.serial_cap or t.serial_exact is distinct from e.serial_exact or t.exclusive_note is distinct from e.exclusive_note or t.numbering_note is distinct from e.numbering_note or t.verification_status is distinct from e.verification_status)
 then raise exception 'Conflicting catalogue_variants identity; refusing overwrite'; end if;
end $$;
insert into public.catalogue_variants(id,set_id,card_id,variant_order,subset,card_number,display_name,parallel,serial_cap,serial_exact,exclusive_note,numbering_note,verification_status) select id,set_id,card_id,variant_order,subset,card_number,display_name,parallel,serial_cap,serial_exact,exclusive_note,numbering_note,verification_status from desired_catalogue_variants on conflict do nothing;
